import type { VariantProps } from "class-variance-authority"
import { cva } from "class-variance-authority"

export { default as Alert } from "./Alert.vue"
export { default as AlertAction } from "./AlertAction.vue"
export { default as AlertDescription } from "./AlertDescription.vue"
export { default as AlertTitle } from "./AlertTitle.vue"

/**
 * alertVariants：Alert 的 cva 变体定义
 *  - 基础：相对定位 + 圆角 + 边框 + 内边距 + 小号文本 + grid 布局（有图标时两列 grid-cols-[..]）
 *    基础边框色用 border-input（显式指定，不再依赖默认 currentColor）
 *  - variant.default：卡片底色（bg-card）
 *  - variant.destructive：危险色；因基础色已写死为 input，需显式补回 border-destructive 红边框
 * @param variant 'default' | 'destructive'，默认 default
 */
export const alertVariants = cva(
  "relative w-full rounded-lg border border-input px-4 py-3 text-sm grid has-[>svg]:grid-cols-[calc(var(--spacing)*4)_1fr] grid-cols-[0_1fr] has-[>svg]:gap-x-3 gap-y-0.5 items-start [&>svg]:size-4 [&>svg]:translate-y-0.5 [&>svg]:text-current",
  {
    variants: {
      variant: {
        default: "bg-card text-card-foreground",
        destructive:
          "text-destructive bg-card border-destructive [&>svg]:text-current *:data-[slot=alert-description]:text-destructive/90",
      },
    },
    defaultVariants: {
      variant: "default",
    },
  },
)

export type AlertVariants = VariantProps<typeof alertVariants>

